INSERT INTO meteo (id, nom, ordre, description, origine, source_ref, remarque) VALUES ('guide/meteo#meteo:brouillard', 'Brouillard', 9, 'Un brouillard dense enveloppe le paysage, noyant les formes dans un voile laiteux. Dans cette obscurité diffuse, seuls les plus rusés tirent avantage de l’incertitude ambiante.', 'annexes', 'Magie Maverick V8 › Météo › B58:T64', NULL);
INSERT INTO meteo (id, nom, ordre, description, origine, source_ref, remarque) VALUES ('guide/meteo#meteo:brouillard-obscur', 'Brouillard obscur', 11, 'Un brouillard obscur s’étend comme une ombre vivante, absorbant la lumière et troublant les sens. Dans cette nuit artificielle, la peur et l’incertitude deviennent des armes redoutables.', 'annexes', 'Magie Maverick V8 › Météo › B72:T78', NULL);
INSERT INTO meteo (id, nom, ordre, description, origine, source_ref, remarque) VALUES ('guide/meteo#meteo:canicule', 'Canicule', 3, 'Une canicule écrasante s’abat sur le paysage, l’air brûlant rendant chaque souffle plus difficile. Sous cette chaleur oppressante, même les plus résistants peinent à maintenir leur énergie.', 'annexes', 'Magie Maverick V8 › Météo › B16:T22', NULL);
INSERT INTO meteo (id, nom, ordre, description, origine, source_ref, remarque) VALUES ('guide/meteo#meteo:champ-magnetique', 'Champ magnétique', 13, 'Un champ magnétique invisible sature l’air d’une énergie étrange, troublant les flux magiques et les perceptions. Les boussoles s’affolent, et même les plus expérimentés peinent à comprendre où est la gauche et la droite.', 'annexes', 'Magie Maverick V8 › Météo › B86:T92', NULL);
INSERT INTO meteo (id, nom, ordre, description, origine, source_ref, remarque) VALUES ('guide/meteo#meteo:crachin-blanc', 'Crachin Blanc', 17, 'Un crachin blanc tombe doucement, enveloppant le monde d’une fine couche de chakra pure. Cette petite brume pousse le chakra des combattant à son paroxysme et permet d''énorme prouesse.', 'annexes', 'Magie Maverick V8 › Météo › B114:T120', NULL);
INSERT INTO meteo (id, nom, ordre, description, origine, source_ref, remarque) VALUES ('guide/meteo#meteo:eclipse', 'Éclipse', 16, 'Une éclipse plonge le monde dans une obscurité surnaturelle, où la lumière du soleil est totalement occultée. Ce phénomène étrange agit fort sur les magies d''Ombre et de Lumière.', 'annexes', 'Magie Maverick V8 › Météo › B107:T113', NULL);
INSERT INTO meteo (id, nom, ordre, description, origine, source_ref, remarque) VALUES ('guide/meteo#meteo:grand-soleil', 'Grand Soleil', 2, 'Un grand soleil inonde le ciel d’une lumière éclatante, réchauffant l’air et éclairsisant fort bien la zone.', 'annexes', 'Magie Maverick V8 › Météo › B9:T15', NULL);
INSERT INTO meteo (id, nom, ordre, description, origine, source_ref, remarque) VALUES ('guide/meteo#meteo:lune-de-sang', 'Lune de sang', 15, 'Une lune de sang s’élève dans le ciel, baignant le monde d’une lueur rouge inquiétante. Sous ce présage funeste, les instincts primaires s’éveillent, et la frontière entre chasseur et proie s’amenuise.', 'annexes', 'Magie Maverick V8 › Météo › B100:T106', NULL);
INSERT INTO meteo (id, nom, ordre, description, origine, source_ref, remarque) VALUES ('guide/meteo#meteo:neige', 'Neige', 6, 'Une fine neige recouvre lentement le paysage, apportant un froid mordant et un silence feutré. Chaque pas devient plus difficile, rendant les déplacements plus lents et méthodiques.', 'annexes', 'Magie Maverick V8 › Météo › B37:T43', NULL);
INSERT INTO meteo (id, nom, ordre, description, origine, source_ref, remarque) VALUES ('guide/meteo#meteo:normal', 'Normal', 1, 'Une météo neutre offre un ciel dégagé parsemé de quelques nuages, où aucun élément ne prend le dessus. La magie y reste stable. Dans cet équilibre parfait, seuls le talent et l’expérience du combattant font la différence.', 'annexes', 'Magie Maverick V8 › Météo › B2:T8', NULL);
INSERT INTO meteo (id, nom, ordre, description, origine, source_ref, remarque) VALUES ('guide/meteo#meteo:orage', 'Orage', 12, 'Un orage éclate, zébrant le ciel d’éclairs aveuglants tandis que le tonnerre gronde avec une puissance assourdissante. Chaque instant peut voir la fureur céleste frapper sans avertissement.', 'annexes', 'Magie Maverick V8 › Météo › B79:T85', NULL);
INSERT INTO meteo (id, nom, ordre, description, origine, source_ref, remarque) VALUES ('guide/meteo#meteo:pluie', 'Pluie', 4, 'Une pluie régulière tombe du ciel, rafraîchissant l’air et imbibant le sol d’humidité.', 'annexes', 'Magie Maverick V8 › Météo › B23:T29', NULL);
INSERT INTO meteo (id, nom, ordre, description, origine, source_ref, remarque) VALUES ('guide/meteo#meteo:pluie-diluvienne', 'Pluie diluvienne', 5, 'Une pluie diluvienne s’abat avec force, transformant le sol en bourbier et réduisant la visibilité. Le vent et l’humidité perturbent également les incantations, rendant tout affrontement plus chaotique.', 'annexes', 'Magie Maverick V8 › Météo › B30:T36', NULL);
INSERT INTO meteo (id, nom, ordre, description, origine, source_ref, remarque) VALUES ('guide/meteo#meteo:pluie-petrole', 'Pluie pétrole', 18, 'Une pluie de pétrole tombe du ciel, noire et épaisse, recouvrant tout d’une couche glissante , infligeant de la corruption à tout le monde.', 'annexes', 'Magie Maverick V8 › Météo › B121:T127', NULL);
INSERT INTO meteo (id, nom, ordre, description, origine, source_ref, remarque) VALUES ('guide/meteo#meteo:puree-de-poix', 'Purée de poix', 10, 'Une purée de poix impénétrable noie le monde dans une obscurité quasi totale, étouffant sons et lumières. Seuls ceux dotés d’un sens aiguisé peuvent naviguer sans errer à l’aveugle.', 'annexes', 'Magie Maverick V8 › Météo › B65:T71', NULL);
INSERT INTO meteo (id, nom, ordre, description, origine, source_ref, remarque) VALUES ('guide/meteo#meteo:saccage-temporel', 'Saccage temporel', 19, 'Un saccage temporel déchire le tissu de la réalité, distordant le temps et créant des décalages où passé, présent et futur s’entrelacent de façon chaotique. Les logiques de vitesse, portée et même initiative sont inversé dans ce chaos.', 'annexes', 'Magie Maverick V8 › Météo › B128:T134', NULL);
INSERT INTO meteo (id, nom, ordre, description, origine, source_ref, remarque) VALUES ('guide/meteo#meteo:tempete-de-neige', 'Tempête de neige', 7, 'Une tempête de neige déchaîne vents glacés et flocons cinglants, réduisant la visibilité à quelques mètres. Le blizzard rend les déplacements périlleux, exposant les imprudents à un destin gelé.', 'annexes', 'Magie Maverick V8 › Météo › B44:T50', NULL);
INSERT INTO meteo (id, nom, ordre, description, origine, source_ref, remarque) VALUES ('guide/meteo#meteo:tempete-de-sable', 'Tempête de sable', 14, 'Une tempête de sable déchaîne des vents furieux, soulevant un mur de particules abrasives qui réentrent dans les vêtements et armures.  Chaque souffle est une lutte, et seuls les plus résistants parviennent à avancer sans faillir.', 'annexes', 'Magie Maverick V8 › Météo › B93:T99', NULL);
INSERT INTO meteo (id, nom, ordre, description, origine, source_ref, remarque) VALUES ('guide/meteo#meteo:vent-violent', 'Vent violent', 8, 'Un vent violent balaie la zone, hurlant à travers les obstacles et rendant l’air instable. Les rafales imprévisibles mettent à l’épreuve même les combattants les plus aguerris', 'annexes', 'Magie Maverick V8 › Météo › B51:T57', NULL);
INSERT INTO meteo (id, nom, ordre, description, origine, source_ref, remarque) VALUES ('guide/meteo#meteo:zone-vide', 'Zone vide', 20, 'Une zone vide s’étend, dénuée de toute énergie magique, où l’air semble étrangement calme et figé. Aucune magie ne fonctionne dans cette zone.', 'annexes', 'Magie Maverick V8 › Météo › B135:T141', NULL);
